parameters.jsCode:
const trig = $('1. Webhook Trigger').first().json.body || {};
let cand = {};
try {
  const res = $('3. Fetch Candidate Context API').first().json;
  cand = res.candidate || res.data || {};
} catch(e) {}

const isOffer = Boolean(
  trig.notification_type === 'offer' ||
  trig.notification_type === 'job_offer' ||
  cand.status === 'Trúng tuyển' ||
  cand.approval_status === 'OFFER_SENT'
);

const isRejection = Boolean(
  !isOffer && (
    trig.notification_type === 'rejection' ||
    trig.notification_type === 'rejection_post_interview' ||
    cand.status === 'Loại' ||
    cand.status === 'Không đạt' ||
    cand.approval_status === 'REJECTED'
  )
);

const isReminder = Boolean(
  !isOffer && !isRejection && (
    trig.notification_type === 'reminder' ||
    trig.notification_type === 'interview_reminder' ||
    trig.type === 'reminder'
  )
);

let candEmail = trig.candidate_email || cand.email;
if (!candEmail || candEmail.includes('ungvien@vku.udn.vn') || candEmail.includes('example.com')) {
  candEmail = 'hoami2113@gmail.com';
}

const salary = trig.salary || cand.salary || 'Thỏa thuận theo năng lực';
const startDate = trig.start_date || 'Theo thỏa thuận sau khi ký kết';

return [{
  json: {
    candidate_id: cand.id || trig.candidate_id,
    candidate_name: trig.candidate_name || cand.full_name || cand.name || "Ứng viên",
    candidate_email: candEmail,
    position: trig.position || cand.applied_position || cand.position || "Vị trí chuyên môn",
    interview_time: trig.interview_time || cand.interview_time || "2026-11-01 09:30:00",
    interviewer: trig.interviewer || cand.interviewer_name || "Hội Đồng Tuyển Dụng VKU",
    meet_link: trig.meet_link || cand.meeting_link || "https://meet.google.com/dfj-amei-jzt",
    focus_topics: trig.focus_topics || "Kiến trúc hệ thống, Khả năng chịu tải",
    salary: salary,
    start_date: startDate,
    is_offer: isOffer,
    is_rejection: isRejection,
    is_reminder: isReminder,
    prompt: isOffer
      ? `Soạn Thư Mời Nhận Việc (Job Offer Letter) trang trọng, chúc mừng ứng viên ${cand.full_name || trig.candidate_name} gia nhập vị trí ${cand.applied_position || trig.position} với mức thu nhập ${salary}, thời gian bắt đầu ${startDate}.`
      : (isRejection
        ? `Soạn thư từ chối mang tính xây dựng cao cho ứng viên ${cand.full_name || trig.candidate_name} vị trí ${cand.applied_position || trig.position}. Cảm ơn và chỉ ra 2 kỹ năng nên trau dồi để ứng tuyển lại trong tương lai.`
        : (isReminder
          ? `Soạn thư nhắc lịch phỏng vấn trang trọng, thân thiện cho ứng viên ${cand.full_name || trig.candidate_name} vị trí ${cand.applied_position || trig.position} sẽ diễn ra lúc ${trig.interview_time || cand.interview_time} trên Google Meet.`
          : `Soạn thư mời phỏng vấn trang trọng kèm Bộ tài liệu chuẩn bị cho ứng viên ${cand.full_name || trig.candidate_name} vị trí ${cand.applied_position || trig.position} vào lúc ${trig.interview_time || cand.interview_time} với Lead ${trig.interviewer || cand.interviewer_name}.`))
  }
}];

return JSON.stringify({
  technical_readiness: ["Ôn tập kiến trúc phân tán & Microservices", "Chuẩn bị demo một dự án tiêu biểu"],
  interview_checklist: ["Kiểm tra webcam & mic trước 10 phút", "Tìm không gian yên tĩnh và đường truyền ổn định"]
});

return JSON.stringify({
  highlight: "Hồ sơ của bạn có nền tảng tư duy lập trình và học vấn tốt.",
  growth_recommendation: "Nếu bổ sung thêm kinh nghiệm triển khai Docker Container trên server thực tế, hồ sơ sẽ vô cùng cạnh tranh."
});

